func liftWasm(h *witgo.Handles, v component.Value) ([]byte, error) {
	vs, err := witgo.Values(v, -1, "wasm")
	if err != nil {
		return nil, err
	}
	out := make([]byte, len(vs))
	for i, e := range vs {
		if out[i], err = witgo.U8(e); err != nil {
			return nil, err
		}
	}
	return out, nil
}

func lowerWasm(h *witgo.Handles, x []byte) component.Value {
	out := make([]component.Value, len(x))
	for i, e := range x {
		out[i] = uint32(e)
	}
	return out
}

