// Root is an instance of a component of the WIT world root.
type Root struct{ inst *component.Instance }

// Instantiate instantiates a component of the world root, with imports implementing
// its imports. opts are passed on to component.Instantiate, for what the
// bindings leave to the host, such as WASI.
func Instantiate(ctx context.Context, r wazy.Runtime, wasm []byte, opts ...component.Option) (*Root, error) {
	var o []component.Option
	inst, err := component.Instantiate(ctx, r, wasm, append(o, opts...)...)
	if err != nil {
		return nil, err
	}
	return &Root{inst: inst}, nil
}

// Instance is the underlying component instance.
func (x *Root) Instance() *component.Instance { return x.inst }

// Close closes the instance.
func (x *Root) Close(ctx context.Context) error { return x.inst.Close(ctx) }

// Wit2 is the export componentized:component/wit@0.1.0.
type Wit2 struct{ inst *component.Instance }

// Wit2 is the instance's export componentized:component/wit@0.1.0.
func (x *Root) Wit2() Wit2 { return Wit2{x.inst} }

// Parse calls the export parse.
func (x Wit2) Parse(ctx context.Context, source WitSource) (witgo.Result[Wit, ErrorCode], error) {
	res, err := x.inst.CallExport(ctx, "componentized:component/wit@0.1.0", "parse", lowerWitSource(nil, source))
	if err != nil {
		var zero witgo.Result[Wit, ErrorCode]
		return zero, err
	}
	if len(res) != 1 {
		var zero witgo.Result[Wit, ErrorCode]
		return zero, fmt.Errorf("%s: %d results", "parse", len(res))
	}
	return liftT25(nil, res[0])
}

// Print calls the export print.
func (x Wit2) Print(ctx context.Context, source WitSource, options *PrintOptions) (witgo.Result[string, ErrorCode], error) {
	res, err := x.inst.CallExport(ctx, "componentized:component/wit@0.1.0", "print", lowerWitSource(nil, source), lowerT28(nil, options))
	if err != nil {
		var zero witgo.Result[string, ErrorCode]
		return zero, err
	}
	if len(res) != 1 {
		var zero witgo.Result[string, ErrorCode]
		return zero, fmt.Errorf("%s: %d results", "print", len(res))
	}
	return liftT29(nil, res[0])
}

// Summarize calls the export summarize.
func (x Wit2) Summarize(ctx context.Context, source WitSource) (witgo.Result[Summary, ErrorCode], error) {
	res, err := x.inst.CallExport(ctx, "componentized:component/wit@0.1.0", "summarize", lowerWitSource(nil, source))
	if err != nil {
		var zero witgo.Result[Summary, ErrorCode]
		return zero, err
	}
	if len(res) != 1 {
		var zero witgo.Result[Summary, ErrorCode]
		return zero, fmt.Errorf("%s: %d results", "summarize", len(res))
	}
	return liftT31(nil, res[0])
}
